import { jsPDF } from "jspdf";
import type { Order,OrderLine,Product } from "../types";

type PdfLine = OrderLine & {
  uom?: string | { name?: string; pack?: string };
  uomName?: string;
  uomId?: number;
};
type PdfOrder = Order & { items?: PdfLine[] };

export function createOrderPdf(order: PdfOrder) {
  const doc = new jsPDF();
  const navy = "#071d55";
  const money = (n: unknown) =>
    n != null && Number.isFinite(Number(n)) ? Number(n).toFixed(2) : "-";
  const text = (
    value: string,
    x: number,
    y: number,
    size = 10,
    bold = false,
    align: "left" | "right" = "left",
  ) => {
    doc.setTextColor(navy);
    doc.setFont("helvetica", bold ? "bold" : "normal");
    doc.setFontSize(size);
    doc.text(value, x, y, { align });
  };
  const header = () => {
    doc.addImage(LOGO, "PNG", 7, 10, 33, 33);
    text("RENGAS", 43, 19, 23, true);
    doc.setFontSize(23);
    doc.setTextColor("#0072ef");
    doc.text("BORONG", 43, 29);
    text("G O O D  P R O D U C T S  •  H A P P I E R  L I V E S", 44, 34, 6.3);
    text("No.12, Jalan Murni 3, Taman Perindustrian Murni,", 44, 41, 8);
    text("81400 Senai, Johor Darul Takzim, Malaysia", 44, 46, 8);
    text("+60 12-710 7621  |  info@rengasborong.in", 44, 52, 8);
    doc.setDrawColor("#9aa2ad");
    doc.setLineWidth(0.2);
    doc.line(145, 12, 145, 53);
    text("ORDER #", 155, 21, 11);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    const size = Math.min(
      22,
      (22 * 47) / Math.max(47, doc.getTextWidth(order.orderNo)),
    );
    text(order.orderNo, 155, 33, size, false);
    text("DATE", 155, 43, 10);
    text(order.date, 155, 51, 11);
    doc.setDrawColor("#315b94");
    doc.line(7, 58, 203, 58);
  };
  header();
  const customer = order.customer;
  const panel = (
    title: string,
    x: number,
    rows: [string, string | undefined][],
  ) => {
    doc.setFillColor("#e6e9ee");
    doc.rect(x, 62, 94, 8, "F");
    text(title, x + 3, 68, 10, true);
    let y = 78;
    for (const [label, value] of rows) {
      doc.setFontSize(9);
      doc.setFont("helvetica", "normal");
      const lines: string[] = doc.splitTextToSize(value || "-", 62);
      text(label, x + 3, y, 9, true);
      text(":", x + 27, y, 9);
      for (const line of lines) {
        text(line, x + 32, y, 9);
        y += 5;
      }
      y += 1;
    }
    return y;
  };
  const left = panel("BILL TO:", 7, [
    ["Customer", customer?.name],
    ["Company", customer?.companyName],
    ["Address", customer?.address],
  ]);
  const right = panel("CONTACT DETAILS:", 109, [
    ["Phone", customer?.phoneNumber],
    ["WhatsApp", customer?.whatsappNumber],
    ["TIN", customer?.tinNumber],
  ]);
  let y = Math.max(103, left + 6, right + 6);
  doc.setDrawColor("#c5cad2");
  doc.line(105, 62, 105, y - 5);
  const widths = [10, 33, 59, 17, 23, 27, 27];
  const headings = [
    ["#"],
    ["Product ID"],
    ["Description"],
    ["UOM"],
    ["Quantity"],
    ["Unit Price", "(RM)"],
    ["Amount", "(RM)"],
  ];
  const row = (
    cells: string[][],
    height: number,
    isHeader = false,
    shaded = false,
  ) => {
    let x = 7;
    cells.forEach((lines, col) => {
      doc.setFillColor(isHeader ? "#e6e9ee" : shaded ? "#f0f1f4" : "#ffffff");
      doc.setDrawColor("#aeb4bd");
      doc.setLineWidth(0.15);
      doc.rect(x, y, widths[col], height, "FD");
      lines.forEach((line, index) => {
        if (isHeader) {
          doc.setFont("helvetica", "bold");
          doc.setFontSize(8.5);
          doc.setTextColor("#111111");
          doc.text(line, x + widths[col] / 2, y + 6 + index * 4, {
            align: "center",
          });
        } else
          text(
            line,
            col >= 4 ? x + widths[col] - 2 : x + 2,
            y + 5 + index * 4.3,
            8.5,
            false,
            col >= 4 ? "right" : "left",
          );
      });
      x += widths[col];
    });
    y += height;
  };
  const nextPage = () => {
    doc.addPage();
    y = 16;
    row(headings, 14, true);
  };
  if (y > 230) {
    doc.addPage();
    y = 16;
  }
  row(headings, 14, true);
  const items = Array.isArray(order.items) ? order.items : [];
  items.forEach((item, index) => {
    const uom =
      typeof item.uom === "string"
        ? item.uom
        : item.uom?.name || item.uom?.pack || item.uomName || "-";
    const values = [
      String(index + 1),
      item.product.code || String(item.product.id),
      item.product.name,
      uom,
      money(item.quantity),
      money(item.unitPrice),
      money(
        item.amount ??
          (item.unitPrice == null ? NaN : item.quantity * item.unitPrice),
      ),
    ];
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    const cells: string[][] = values.map((value, col) =>
      doc.splitTextToSize(value, widths[col] - 4),
    );
    const length = Math.max(...cells.map((cell) => cell.length));
    if (y + Math.max(8, length * 4.3 + 4) > 245) nextPage();
    for (let offset = 0; offset < length; ) {
      const take = Math.min(
        length - offset,
        Math.max(1, Math.floor((245 - y - 4) / 4.3)),
      );
      row(
        cells.map((cell) => cell.slice(offset, offset + take)),
        Math.max(8, take * 4.3 + 4),
        false,
        index % 2 === 1,
      );
      offset += take;
      if (offset < length) nextPage();
    }
  });
  if (!items.length)
    row([[""], [""], ["Items unavailable"], [""], [""], [""], [""]], 10);
  y += 5;
  if (y > 247) {
    doc.addPage();
    y = 16;
  }
  doc.setFillColor("#e6e9ee");
  doc.setDrawColor("#aeb4bd");
  doc.rect(117, y, 45, 12, "FD");
  doc.rect(162, y, 41, 12, "FD");
  text("GRAND TOTAL", 121, y + 8, 11, true);
  text(`RM ${money(order.total)}`, 200, y + 8, 11, false, "right");
  const pages = doc.getNumberOfPages();
  for (let page = 1; page <= pages; page++) {
    doc.setPage(page);
    doc.setDrawColor("#315b94");
    doc.line(10, 278, 200, 278);
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(navy);
    doc.text("T H A N K  Y O U  F O R  Y O U R  B U S I N E S S !", 105, 287, {
      align: "center",
    });
    if (pages > 1) text(`${page} / ${pages}`, 201, 293, 7, false, "right");
  }
  return doc;
}
export function withOrderUoms(order: PdfOrder, products: Product[]): PdfOrder {
  return {
    ...order,
    items: order.items?.map((item) => {
      if (
        typeof item.uom === "string"
          ? item.uom.trim()
          : item.uom?.name || item.uom?.pack || item.uomName
      )
        return item;
      const product = products.find(
        (product) => product.id === item.product.id,
      );
      const uom =
        item.uomId != null
          ? product?.uoms.find((unit) => unit.id === item.uomId)
          : product?.uoms.length === 1
            ? product.uoms[0]
            : undefined;
      return uom ? { ...item, uom: uom.name || uom.pack } : item;
    }),
  };
}

export async function downloadOrderPdf(order: PdfOrder) {
  // Older order responses omit UOM. Use the catalog only for an unambiguous match.
  let printable = order;
  if (
    order.items?.some(
      (item) =>
        !(typeof item.uom === "string"
          ? item.uom.trim()
          : item.uom?.name || item.uom?.pack || item.uomName),
    )
  ) {
    const { api } = await import("./api");
    printable = withOrderUoms(order, await api.products());
  }
  const filename = (order.orderNo || String(order.id)).replace(
    /[^a-zA-Z0-9_-]/g,
    "_",
  );
  createOrderPdf(printable).save(`Order-${filename}.pdf`);
}
const LOGO =
  "data:image/png;base64,";
